const mapCtx=$('minimap').getContext('2d');function drawMap(){const c=mapCtx,w=192;c.clearRect(0,0,w,w);c.fillStyle='#163d3e';c.fillRect(0,0,w,w);c.strokeStyle='#78b79f1f';c.lineWidth=1;for(let r=25;r<110;r+=25){c.beginPath();c.arc(96,96,r,0,TAU);c.stroke();}c.fillStyle='#4c929c';c.beginPath();c.ellipse(70,119,18,24,-.3,0,TAU);c.fill();const map=(x,z)=>[96+x*.39,96-z*.39];for(const a of animals){if(!a.available)continue;const p=map(a.root.position.x,a.root.position.z);c.fillStyle=a.type==='sheep'?'#d7e6ca':'#efa578';c.fillRect(p[0]-1,p[1]-1,2,2);}eggs.forEach(e=>{if(e.collected)return;const p=map(e.root.position.x,e.root.position.z);c.fillStyle=e.shield==='ice'?'#8edfff':e.shield==='flame'?'#efa475':'#f9d386';c.beginPath();c.arc(...p,3,0,TAU);c.fill();});let p=map(nestPos.x,nestPos.z);c.strokeStyle='#ecdbb2';c.strokeRect(p[0]-3,p[1]-3,6,6);p=map(friend.root.position.x,friend.root.position.z);c.fillStyle='#93bcff';c.beginPath();c.arc(...p,3,0,TAU);c.fill();p=map(dragon.root.position.x,dragon.root.position.z);c.save();c.translate(...p);c.rotate(state.heading);c.fillStyle='#a9ffe0';c.beginPath();c.moveTo(0,-6);c.lineTo(4,5);c.lineTo(0,3);c.lineTo(-4,5);c.closePath();c.fill();c.restore();c.fillStyle='#bbd6c8';c.font='9px Segoe UI';c.fillText('N',92,12);}
