function uiTick(dt){toastTick-=dt;if(toastQueue.length&&toastTick<=0){const {title,desc}=toastQueue.shift();const o=document.createElement('div');o.className='toast';const b=document.createElement('b');b.textContent=title;o.append(b,document.createTextNode(desc));$('toastArea').append(o);toastTick=2;setTimeout(()=>{o.classList.add('fade');setTimeout(()=>o.remove(),450);},5200);while($('toastArea').children.length>3)$('toastArea').firstChild.remove();}milestoneTimer-=dt;if(milestoneTimer<=0)$('milestone').hidden=true;$('timeLabel').textContent=isNight()?'Noc świetlistych ogonów':nightAmount()>.1?'Złoty zmierzch':'Słoneczna dolina';$('sunIcon').textContent=isNight()?'☾':'☀';}
let last=performance.now(),worldTime=0;function frame(now){requestAnimationFrame(frame);const dt=Math.min(.05,(now-last)/1000);last=now;if(!state.paused){worldTime+=dt;if(state.started)tick(dt,worldTime);else{const a=worldTime*.045,pp=dragon.root.position;camera.position.set(pp.x+28+Math.sin(a)*13,pp.y+14,pp.z+30+Math.cos(a)*6);camera.lookAt(pp.x,pp.y+5,pp.z);dragon.wings[0].rotation.z=.25;dragon.wings[1].rotation.z=-.25;}updateWorld(dt,worldTime);if(state.started&&!state.paused){camera.updateMatrixWorld();updateFlightAim();updateGuides();if(!input.showTouch&&innerWidth>700)drawMap();}uiTick(dt);}renderer.render(scene,camera);}
